"""Swarm CI Dashboard Generator - Aggregates test results, coverage, and chaos metrics."""
import json
import os
import sqlite3
from datetime import datetime, timedelta
from pathlib import Path
from typing import Dict, List

import pandas as pd
import plotly.express as px
import plotly.graph_objects as go
from jinja2 import Environment, FileSystemLoader


class DashboardBuilder:
    def __init__(self, artifacts_dir: Path, output_dir: Path):
        self.artifacts = artifacts_dir
        self.output = output_dir
        self.db_path = output_dir / "metrics.db"
        self._init_db()

    def _init_db(self):
        """Initialize SQLite database for historical metrics."""
        self.conn = sqlite3.connect(self.db_path)
        self.conn.execute("""
            CREATE TABLE IF NOT EXISTS test_runs (
                id INTEGER PRIMARY KEY,
                timestamp TEXT,
                suite TEXT,
                total INTEGER,
                passed INTEGER,
                failed INTEGER,
                duration REAL
            )
        """)
        self.conn.execute("""
            CREATE TABLE IF NOT EXISTS coverage (
                id INTEGER PRIMARY KEY,
                timestamp TEXT,
                line_coverage REAL,
                branch_coverage REAL
            )
        """)
        self.conn.execute("""
            CREATE TABLE IF NOT EXISTS chaos_events (
                id INTEGER PRIMARY KEY,
                timestamp TEXT,
                experiment TEXT,
                success BOOLEAN,
                recovery_time REAL
            )
        """)

    def parse_junit(self, path: Path) -> Dict:
        """Parse JUnit XML results."""
        import xml.etree.ElementTree as ET
        tree = ET.parse(path)
        root = tree.getroot()
        return {
            "total": int(root.get("tests", 0)),
            "failed": int(root.get("failures", 0)) + int(root.get("errors", 0)),
            "duration": float(root.get("time", 0)),
        }

    def parse_coverage(self, path: Path) -> Dict:
        """Parse coverage JSON summary."""
        data = json.loads(path.read_text())
        totals = data["totals"]
        return {
            "line_coverage": totals["percent_covered"],
            "branch_coverage": (
                totals["num_branches"] - totals["missing_branches"]
            ) / max(totals["num_branches"], 1) * 100,
        }

    def ingest_results(self):
        """Ingest all artifacts into database."""
        timestamp = datetime.utcnow().isoformat()

        # Parse test results
        for result_file in self.artifacts.glob("**/results-*.xml"):
            suite = result_file.parent.name
            results = self.parse_junit(result_file)
            self.conn.execute(
                "INSERT INTO test_runs VALUES (?, ?, ?, ?, ?, ?, ?)",
                (None, timestamp, suite, results["total"],
                 results["total"] - results["failed"], results["failed"],
                 results["duration"]),
            )

        # Parse coverage
        for cov_file in self.artifacts.glob("**/coverage-summary.json"):
            cov = self.parse_coverage(cov_file)
            self.conn.execute(
                "INSERT INTO coverage VALUES (?, ?, ?, ?)",
                (None, timestamp, cov["line_coverage"], cov["branch_coverage"]),
            )

        # Parse chaos results
        chaos_file = self.artifacts / "chaos-report.json"
        if chaos_file.exists():
            chaos_data = json.loads(chaos_file.read_text())
            for event in chaos_data["events"]:
                self.conn.execute(
                    "INSERT INTO chaos_events VALUES (?, ?, ?, ?, ?)",
                    (None, event["timestamp"], event["experiment"],
                     event["success"], event["recovery_time"]),
                )

        self.conn.commit()

    def generate_plots(self) -> Dict[str, str]:
        """Generate Plotly visualizations."""
        plots = {}

        # Test trend over time
        df = pd.read_sql_query(
            "SELECT timestamp, suite, passed, failed FROM test_runs ORDER BY timestamp",
            self.conn,
        )
        if not df.empty:
            fig = px.line(df, x="timestamp", y=["passed", "failed"],
                          color="suite", title="Test Results Trend")
            plots["test_trend"] = fig.to_html(full_html=False)

        # Coverage trend
        df_cov = pd.read_sql_query(
            "SELECT timestamp, line_coverage, branch_coverage FROM coverage ORDER BY timestamp",
            self.conn,
        )
        if not df_cov.empty:
            fig = go.Figure()
            fig.add_trace(go.Scatter(x=df_cov["timestamp"],
                                     y=df_cov["line_coverage"],
                                     name="Line Coverage"))
            fig.add_trace(go.Scatter(x=df_cov["timestamp"],
                                     y=df_cov["branch_coverage"],
                                     name="Branch Coverage"))
            fig.add_hline(y=85, line_dash="dash", line_color="red",
                          annotation_text="Threshold")
            plots["coverage_trend"] = fig.to_html(full_html=False)

        # Chaos success rate
        df_chaos = pd.read_sql_query(
            "SELECT experiment, success, recovery_time FROM chaos_events",
            self.conn,
        )
        if not df_chaos.empty:
            success_rate = df_chaos["success"].mean() * 100
            fig = go.Figure(go.Indicator(
                mode="gauge+number",
                value=success_rate,
                title={"text": "Chaos Experiment Success Rate"},
                gauge={"axis": {"range": [0, 100]},
                       "bar": {"color": "green" if success_rate > 90 else "orange"},
                       "steps": [
                           {"range": [0, 70], "color": "red"},
                           {"range": [70, 90], "color": "yellow"},
                           {"range": [90, 100], "color": "green"},
                       ]},
            ))
            plots["chaos_success"] = fig.to_html(full_html=False)

        return plots

    def build(self):
        """Generate final HTML dashboard."""
        self.ingest_results()
        plots = self.generate_plots()

        env = Environment(loader=FileSystemLoader("dashboard/templates"))
        template = env.get_template("dashboard.html")

        # Get latest metrics
        latest_cov = self.conn.execute(
            "SELECT * FROM coverage ORDER BY timestamp DESC LIMIT 1"
        ).fetchone()
        latest_test = self.conn.execute(
            "SELECT * FROM test_runs ORDER BY timestamp DESC LIMIT 1"
        ).fetchone()

        html = template.render(
            plots=plots,
            latest_coverage=latest_cov,
            latest_test=latest_test,
            generated_at=datetime.utcnow().isoformat(),
        )

        self.output.mkdir(parents=True, exist_ok=True)
        (self.output / "index.html").write_text(html)
        print(f"Dashboard generated at {self.output / 'index.html'}")


if __name__ == "__main__":
    builder = DashboardBuilder(
        artifacts_dir=Path("artifacts"),
        output_dir=Path("dashboard/build"),
    )
    builder.build()
